using System.ComponentModel.DataAnnotations;
using Bingo.Web.Security;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
namespace Bingo.Web.Pages.Account;

public sealed class OnboardingModel(AccountIdentityService identities, AccountAuthenticationService authentication, DiscordOnboardingStateService onboardingState, Microsoft.Extensions.Localization.IStringLocalizer<SharedResource> text, Microsoft.Extensions.Logging.ILogger<OnboardingModel> logger) : PageModel { [BindProperty] public InputModel Input { get; set; } = new(); public IActionResult OnGet() => onboardingState.TryRead(Request, out _) ? Page() : RedirectToPage("Login"); public async Task<IActionResult> OnPostAsync(CancellationToken ct) { if (!onboardingState.TryRead(Request, out var state)) return RedirectToPage("Login"); if (!ModelState.IsValid) return Page(); try { var account = await identities.CompleteOnboardingAsync(state.DiscordUserId, state.DisplayName, Input.Username, Input.OsrsCharacterName, Input.Password, ct); onboardingState.Consume(Response, state); await HttpContext.SignInAsync(Microsoft.AspNetCore.Authentication.Cookies.CookieAuthenticationDefaults.AuthenticationScheme, authentication.CreatePrincipal(account, "discord")); TempData["StatusMessage"] = text["Your account is ready."].Value; TempData[Bingo.Web.UI.UiMessage.TypeKey] = Bingo.Web.UI.UiMessageType.Success.ToString(); return RedirectToPage("/Index"); } catch (InvalidOperationException ex) { ModelState.AddModelError(string.Empty, SafeUserFailure.Message(text, logger, ex)); return Page(); } } public sealed class InputModel { [Required(ErrorMessage = "A public username is required."), StringLength(100, MinimumLength = 1), Display(Name = "Website username")] public string Username { get; set; } = string.Empty; [Required(ErrorMessage = "An OSRS character name is required."), StringLength(100, MinimumLength = 1), Display(Name = "First OSRS character")] public string OsrsCharacterName { get; set; } = string.Empty; [Required(ErrorMessage = "A password is required."), StringLength(200, MinimumLength = 10, ErrorMessage = "Passwords must be between 10 and 200 characters."), DataType(DataType.Password), Display(Name = "Password")] public string Password { get; set; } = string.Empty; [Required(ErrorMessage = "Confirm your password."), Compare(nameof(Password), ErrorMessage = "The passwords do not match."), DataType(DataType.Password), Display(Name = "Confirm password")] public string ConfirmPassword { get; set; } = string.Empty; } }
